-  position: relative;
-}
-.touch-expand-xs::before {
-  content: '';
-  position: absolute;
-  inset-inline: 0;
-  inset-block: -8px;
-}
-.touch-expand-sm {
-  position: relative;
-}
-.touch-expand-sm::before {
-  content: '';
-  position: absolute;
-  inset-inline: 0;
