-}
-.touch-expand-iconbtn {
-  position: relative;
-}
-.touch-expand-iconbtn::before {
-  content: '';
-  position: absolute;
-  inset: -8px;
+.touch-expand-xs,
+.touch-expand-sm,
+.touch-expand-iconbtn {
+  position: relative;
+}
+
+@media (pointer: coarse) {
+  .touch-expand-xs,
+  .touch-expand-sm,
+  .touch-expand-iconbtn {
+    min-height: 44px;
+  }
+
+  .touch-expand-iconbtn {
+    min-width: 44px;
+  }
