+	b, err := os.ReadFile("/sys/fs/cgroup/memory.max")
+	if err != nil {
+		return 0, false
+	}
+	raw := strings.TrimSpace(string(b))
+	if raw == "max" {
+		return 0, false
+	}
+	limit, err := strconv.ParseInt(raw, 10, 64)
+	if err != nil || limit <= 0 || (hostTotal > 0 && limit >= hostTotal) {
+		return 0, false
+	}
+	return limit, true
